await page.screenshot({ path: "/tmp/post-list.png", fullPage: true });

const summaryText = await page.locator('p[class*="summary"]').textContent().catch(() => null);
console.log("Summary text:", summaryText);
console.log("Console errors:", errors);

await browser.close();

